CREATE DATABASE IF NOT EXISTS lab_manage CHARACTER SET utf8mb4 COLLATE utf8mb4_0900_ai_ci;
USE lab_manage;
CREATE TABLE role (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(32) NOT NULL UNIQUE, name VARCHAR(64) NOT NULL);
CREATE TABLE campus_identity (id BIGINT PRIMARY KEY AUTO_INCREMENT, identity_no VARCHAR(9) NOT NULL UNIQUE, real_name VARCHAR(64) NOT NULL, person_type VARCHAR(20) NOT NULL, default_role_code VARCHAR(32) NOT NULL, active BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(default_role_code) REFERENCES role(code), CHECK(person_type IN ('STUDENT','STAFF')), CHECK((person_type='STUDENT' AND identity_no REGEXP '^[0-9]{9}$') OR (person_type='STAFF' AND identity_no REGEXP '^[0-9]{7}$')));
CREATE TABLE lab_user (id BIGINT PRIMARY KEY AUTO_INCREMENT, username VARCHAR(64) NOT NULL UNIQUE, password_hash VARCHAR(100) NOT NULL, real_name VARCHAR(64) NOT NULL, email VARCHAR(128) NOT NULL, phone VARCHAR(32) NOT NULL, identity_id BIGINT NOT NULL UNIQUE, credit_score DECIMAL(5,1) NOT NULL DEFAULT 100.0, credit_recovered_on DATE, enabled BOOLEAN NOT NULL DEFAULT TRUE, created_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(identity_id) REFERENCES campus_identity(id));
CREATE TABLE user_role (user_id BIGINT NOT NULL, role_id BIGINT NOT NULL, PRIMARY KEY(user_id,role_id), FOREIGN KEY(user_id) REFERENCES lab_user(id), FOREIGN KEY(role_id) REFERENCES role(id));
CREATE TABLE laboratory (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(100) NOT NULL UNIQUE, location VARCHAR(200) NOT NULL, open_time TIME NOT NULL DEFAULT '08:00:00', close_time TIME NOT NULL DEFAULT '22:00:00', enabled BOOLEAN NOT NULL DEFAULT TRUE);
CREATE TABLE lab_admin_lab (user_id BIGINT NOT NULL, lab_id BIGINT NOT NULL, PRIMARY KEY(user_id,lab_id), FOREIGN KEY(user_id) REFERENCES lab_user(id), FOREIGN KEY(lab_id) REFERENCES laboratory(id));
CREATE TABLE lab_auto_approval (lab_id BIGINT PRIMARY KEY, enabled_until DATETIME NOT NULL, enabled_by BIGINT NOT NULL, updated_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(lab_id) REFERENCES laboratory(id), FOREIGN KEY(enabled_by) REFERENCES lab_user(id));
CREATE TABLE equipment_category (id BIGINT PRIMARY KEY AUTO_INCREMENT, name VARCHAR(80) NOT NULL UNIQUE, description VARCHAR(500));
CREATE TABLE equipment (id BIGINT PRIMARY KEY AUTO_INCREMENT, code VARCHAR(64) NOT NULL UNIQUE, name VARCHAR(120) NOT NULL, category_id BIGINT NOT NULL, lab_id BIGINT NOT NULL, brand_model VARCHAR(160), location VARCHAR(160), owner_id BIGINT, description TEXT, usage_rules TEXT, image_url VARCHAR(500), purchase_date DATE, status VARCHAR(20) NOT NULL DEFAULT 'AVAILABLE', version BIGINT NOT NULL DEFAULT 0, created_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(category_id) REFERENCES equipment_category(id), FOREIGN KEY(lab_id) REFERENCES laboratory(id), FOREIGN KEY(owner_id) REFERENCES lab_user(id), INDEX idx_equipment_filter(lab_id,category_id,status));
CREATE TABLE reservation (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, equipment_id BIGINT NOT NULL, starts_at DATETIME NOT NULL, ends_at DATETIME NOT NULL, purpose VARCHAR(500) NOT NULL, participants INT NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', reject_reason VARCHAR(32), fulfillment_status VARCHAR(24) NOT NULL DEFAULT 'NOT_STARTED', submitted_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), reviewer_id BIGINT, review_comment VARCHAR(500), FOREIGN KEY(user_id) REFERENCES lab_user(id), FOREIGN KEY(equipment_id) REFERENCES equipment(id), FOREIGN KEY(reviewer_id) REFERENCES lab_user(id), INDEX idx_reservation_conflict(equipment_id,status,starts_at,ends_at), CHECK(ends_at > starts_at), CHECK(participants > 0));
CREATE TABLE reservation_review (id BIGINT PRIMARY KEY AUTO_INCREMENT, reservation_id BIGINT NOT NULL, reviewer_id BIGINT, decision VARCHAR(20) NOT NULL, comment VARCHAR(500), created_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(reservation_id) REFERENCES reservation(id), FOREIGN KEY(reviewer_id) REFERENCES lab_user(id));
CREATE TABLE repair_ticket (id BIGINT PRIMARY KEY AUTO_INCREMENT, equipment_id BIGINT NOT NULL, reporter_id BIGINT NOT NULL, fault_type VARCHAR(80) NOT NULL, description TEXT NOT NULL, image_urls TEXT, status VARCHAR(20) NOT NULL DEFAULT 'OPEN', assignee_id BIGINT, result TEXT, cost DECIMAL(10,2), created_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), updated_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(equipment_id) REFERENCES equipment(id), FOREIGN KEY(reporter_id) REFERENCES lab_user(id), FOREIGN KEY(assignee_id) REFERENCES lab_user(id), INDEX idx_repair_status(status,equipment_id));
CREATE TABLE repair_record (id BIGINT PRIMARY KEY AUTO_INCREMENT, ticket_id BIGINT NOT NULL, operator_id BIGINT NOT NULL, status VARCHAR(20) NOT NULL, note TEXT, cost DECIMAL(10,2), created_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(ticket_id) REFERENCES repair_ticket(id), FOREIGN KEY(operator_id) REFERENCES lab_user(id));
CREATE TABLE notification (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, title VARCHAR(160) NOT NULL, content VARCHAR(1000) NOT NULL, read_at DATETIME, created_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(user_id) REFERENCES lab_user(id), INDEX idx_notice_user(user_id,read_at,created_at));
CREATE TABLE operation_log (id BIGINT PRIMARY KEY AUTO_INCREMENT, operator_id BIGINT, action VARCHAR(100) NOT NULL, target_type VARCHAR(50) NOT NULL, target_id BIGINT, detail JSON, created_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(operator_id) REFERENCES lab_user(id), INDEX idx_operation_created(created_at));
CREATE TABLE auto_approval_rule (id BIGINT PRIMARY KEY AUTO_INCREMENT, scope_type VARCHAR(16) NOT NULL, scope_id BIGINT NOT NULL DEFAULT 0, action VARCHAR(16) NOT NULL, enabled_until DATETIME NOT NULL, enabled_by BIGINT NOT NULL, updated_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(enabled_by) REFERENCES lab_user(id), UNIQUE KEY uk_auto_rule_scope(scope_type,scope_id), INDEX idx_auto_rule_active(enabled_until));
CREATE TABLE credit_ledger (id BIGINT PRIMARY KEY AUTO_INCREMENT, user_id BIGINT NOT NULL, reservation_id BIGINT, delta DECIMAL(4,1) NOT NULL, reason VARCHAR(40) NOT NULL, idempotency_key VARCHAR(120) NOT NULL UNIQUE, created_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), FOREIGN KEY(user_id) REFERENCES lab_user(id), FOREIGN KEY(reservation_id) REFERENCES reservation(id));
CREATE TABLE reservation_appeal (id BIGINT PRIMARY KEY AUTO_INCREMENT, reservation_id BIGINT NOT NULL, applicant_id BIGINT NOT NULL, reason VARCHAR(1000) NOT NULL, status VARCHAR(20) NOT NULL DEFAULT 'PENDING', reviewer_id BIGINT, review_comment VARCHAR(1000), created_at DATETIME NOT NULL DEFAULT (UTC_TIMESTAMP()), reviewed_at DATETIME, FOREIGN KEY(reservation_id) REFERENCES reservation(id), FOREIGN KEY(applicant_id) REFERENCES lab_user(id), FOREIGN KEY(reviewer_id) REFERENCES lab_user(id), UNIQUE KEY uk_appeal_reservation(reservation_id));
